#[test]
fn a_write_stops_at_the_put_that_crosses_the_limit() {
    assert_eq!(LIMIT_ROWS.len(), 109);
    let wrong = wrong_rows(LIMIT_ROWS);
    assert!(
        wrong.is_empty(),
        "{} of {}:\n{}",
        wrong.len(),
        LIMIT_ROWS.len(),
        wrong.join("\n")
    );
}
